-- gen596: 30 zone cambiate, 61 tessere
-- 7fe37f874d86519e243ebab5686a6e2b (755150) → 46881a1596b5bcb814f3431a5a1c7f13 (792436)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = '46881a1596b5bcb814f3431a5a1c7f13' as combacia
from kv_store where key like 'tmp:gen596:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen596:p%')
where key='app:jsx:src'
  and md5(value) = '7fe37f874d86519e243ebab5686a6e2b'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen596:p%') = '46881a1596b5bcb814f3431a5a1c7f13';

update kv_store set value = '{"len":792436,"ver":"gen-5.96"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = '46881a1596b5bcb814f3431a5a1c7f13';

delete from kv_store where key like 'tmp:gen596:p%';
